// cadset.js — job-local drawing code for this project (kept beside the project file, not in the installed skill).
// Job type "cadset": a full sheet set whose linework comes from CAD. It is not based on a kit view.
// What is particular to this job type (see "Job-specific drawing code" in references/writing-views.md):
//   - "cad" sheets: windows of a CAD sheet placed in kit panels at true paper size, with overlays, inserts and marks
//   - native panels for notes and tables (html), grey or white placeholder boxes, a cover built from the same parts
//   - its own drawer for CAD sheet data (cadSvg), a close copy of the kit's library-detail drawer
//   - one more audit check: every CAD window prints at the size it was plotted
//   - a copyright line in the title block
// The CAD sheet data (DWG_SHEETS) is the last line of this file.
'use strict';

// cadset - job type for a set whose linework comes from the project DWG files.
// The Oasis-Blueprints DWG converter writes each CAD sheet as data (DWG_SHEETS, above) and cadSvg redraws it in the
// kit's pens and fonts. A sheet here places one or more windows ("crops") of a CAD sheet inside the kit's frame, band
// and title block at true paper size, so every scale stated on the drawing still holds. No value is added here.
//
// Project file:  geometry.sheets["A1.0"] = { tight, panels: [ { page, crop:[x0,y0,x1,y1] (inches from the CAD sheet's
//   top-left), x, y, w, h (inches inside the sheet body), num, title, note, scale, den, footer:false, nts:true, pics:[] } |
//   { text:true, title, items:[...], x, y, w, h, red:true } ] }
//   geometry.coverView = { page, crop, title, note }  the picture on the cover (not to scale).

const BODY_W = 31.8, BODY_H = 22.6;   // drawing area of a sheet below the status band, inches

class LibView { constructor(den, id) { this.den = den; this.id = id; this.u = den / 72; this.out = []; this.defs = []; } ext() {} svg() { return { defs: this.defs.join(''), body: this.out.join('') }; } }
// Draw every source sheet once, off-screen, in paper inches (y down from the sheet's top edge is -y in the data).
function cadDefs() {
  if (document.getElementById('cad-src')) return;
  const d = document.createElement('div'); d.id = 'cad-src'; d.style.cssText = 'position:absolute;left:0;top:0;width:0;height:0;overflow:hidden';
  for (const ed of (PROJECT.geometry.textEdits || [])) { const S = DWG_SHEETS[ed.sheet]; if (!S || S._ed) continue;   // wording changed on the office's instruction; listed in the project file
    for (const g of S.groups) for (const p of g.prims) if (p[0] === 'T') { const L = p[7], Wd = p[8] || [];
      for (let i = 0; i < L.length; i++) { if (!L[i].includes(ed.find)) continue; const was = L[i]; L[i] = was.split(ed.find).join(ed.replace); if (L[i] !== was) Wd[i] = 0;
        (ed.lines || []).forEach((x, k) => { if (L[i + 1 + k] === '') { L[i + 1 + k] = x; Wd[i + 1 + k] = 0; } else { L.splice(i + 1 + k, 0, x); Wd.splice(i + 1 + k, 0, 0); } }); i += (ed.lines || []).length; } } }
  for (const ed of (PROJECT.geometry.textEdits || [])) if (DWG_SHEETS[ed.sheet]) DWG_SHEETS[ed.sheet]._ed = 1;
  d.innerHTML = Object.keys(DWG_SHEETS).map(key => { const s = DWG_SHEETS[key]; let defs = '', body = '';
    if (s.svg) return `<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0"><g id="pg-${key}" class="plot">${s.svg}</g></svg>`;
    s.groups.forEach((g, k) => { const o = cadSvg({ id: key + 'g' + k, den: 1, st: g.st, pats: g.pats, prims: g.prims }); defs += o.defs;
      if (g.clip) { const id = 'vp-' + key + '-' + k; defs += `<clipPath id="${id}"><rect x="${g.clip[0]}" y="${-g.clip[3]}" width="${r3(g.clip[2] - g.clip[0])}" height="${r3(g.clip[3] - g.clip[1])}"/></clipPath>`; body += `<g clip-path="url(#${id})">${o.body}</g>`; } else body += o.body; });
    return `<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0"><defs>${defs}</defs><g id="pg-${key}">${body}</g></svg>`; }).join('');
  document.body.insertBefore(d, document.body.firstChild);
}
// a window of a source sheet. crop is in inches from the sheet's top-left corner. f = 1 keeps true size; any other f is "not to scale".
// Tables the converter keeps as HTML (schedules) and pictures pasted from the plots ride along in the same window.
function cadView(page, crop, f = 1, pics, ins, noOv, marks, shade, over) {
  const S = DWG_SHEETS[page]; if (!S) return `<div class="blank">missing sheet ${esc(page)}</div>`;
  const [x0, y0, x1, y1] = crop, w = x1 - x0, h = y1 - y0, bx = S.box[0], by = -S.box[3];
  const svg = `<svg class="cadv" data-page="${esc(page)}" data-w="${r3(w)}" ${f === 1 ? '' : 'data-nts="1" '}width="${r3(w * f)}in" height="${r3(h * f)}in" viewBox="${r3(bx + x0)} ${r3(by + y0)} ${r3(w)} ${r3(h)}" style="overflow:hidden;display:block" xmlns="http://www.w3.org/2000/svg"><use href="#pg-${esc(page)}"/></svg>`;
  const ov = f === 1 && !noOv ? (S.overlays || []).map(o => `<div class="ov" style="left:${r3(o.x - x0)}in;top:${r3(o.y - y0)}in;width:${o.w}in">${o.html}</div>`).join('') : '';
  const im = (pics || []).map(p => `<img src="${esc(p.src)}" alt="${esc(p.alt || '')}" style="position:absolute;left:${r3((p.x - x0) * f)}in;top:${r3((p.y - y0) * f)}in;width:${r3(p.w * f)}in;height:${r3(p.h * f)}in">`).join('');
  // boxes of this set's own content laid over a cell of the CAD sheet (sheet index, a map still to come): white, so the cell underneath is covered
  const bx2 = (ins || []).map(n => `<div class="cadin${n.reserved ? ' rsv' : ''}${n.note ? ' ntb' : ''}" style="left:${r3((n.x - x0) * f)}in;top:${r3((n.y - y0) * f)}in;width:${r3(n.w * f)}in;height:${r3(n.h * f)}in">${n.html}</div>`).join('');
  // callouts this set adds on the office's instruction: a leader with an arrowhead and its text, in inches from the CAD sheet's top-left corner
  const fz = shade && (DWG_SHEETS[shade] || {}).flood;      // light tint over the flood zone, from the zone's own outline in the DWG
  const sf = shade && (DWG_SHEETS[shade] || {}).silt; let sfx = '';      // silt fence drawn bold over the plot, with its x marks
  const sfb = shade && (DWG_SHEETS[shade] || {}).sf || [];
  for (const run of (sf || [])) { const sf = run; let acc = 0; const step = 0.42, t = 0.05; for (let i = 0; i + 1 < sf.length; i++) { const [ax, ay] = sf[i], [bx, by] = sf[i + 1], L = Math.hypot(bx - ax, by - ay); let d = step - acc;
      while (d <= L) { const x = ax + (bx - ax) * d / L, y = ay + (by - ay) * d / L; sfx += `M${r3(x - t)} ${r3(y - t)}L${r3(x + t)} ${r3(y + t)}M${r3(x - t)} ${r3(y + t)}L${r3(x + t)} ${r3(y - t)}`; d += step; } acc = (acc + L) % step; } }
  const mk = (marks || []).length || fz || sf || over ? `<svg class="cadmk" viewBox="${x0} ${y0} ${r3(w)} ${r3(h)}" style="position:absolute;left:0;top:0;width:100%;height:100%" xmlns="http://www.w3.org/2000/svg">${sf ? sf.map(run => `<polyline class="sfw" points="${run.map(q => q.join(',')).join(' ')}"/><polyline class="sf" points="${run.map(q => q.join(',')).join(' ')}"/>`).join('') + `<path class="sf" d="${sfx}"/>` + sfb.map(c => `<text class="sfb" x="${c[0]}" y="${r3(c[1] + 0.055)}">SF</text>`).join('') : ''}${over || ''}${fz ? `<polygon class="fz" points="${fz.map(q => q.join(',')).join(' ')}"/>` : ''}${(marks || []).map(m => { const [a, b] = m.pts, L = Math.hypot(b[0] - a[0], b[1] - a[1]), ux = (b[0] - a[0]) / L, uy = (b[1] - a[1]) / L, s = 0.11, t = 0.032;
    return `<polyline points="${m.pts.map(q => q.join(',')).join(' ')}"/><path class="ah" d="M${a[0]} ${a[1]}L${r3(a[0] + ux * s - uy * t)} ${r3(a[1] + uy * s + ux * t)}L${r3(a[0] + ux * s + uy * t)} ${r3(a[1] + uy * s - ux * t)}Z"/>${m.text.map((l, i) => `<text x="${m.tx}" y="${r3(m.ty + i * 0.165)}">${esc(l)}</text>`).join('')}`; }).join('')}</svg>` : '';
  return `<div class="cadw" style="position:relative;flex:0 0 auto;width:${r3(w * f)}in;height:${r3(h * f)}in;overflow:hidden">${svg}${ov}${bx2}${im}${mk}</div>`;
}
const at = p => `position:absolute;left:${p.x}in;top:${p.y}in;width:${p.w}in;height:${p.h}in`;

function coverBits(P, p) {
  if (p.kind === 'job') return `<section class="panel" style="${at(p)}"><div class="pad job big" data-fit style="flex:1 1 0"><label>The job</label><h2 style="font-size:${p.size || 24}pt">${esc(P.summary.headline)}</h2><p>${esc(P.summary.text)}</p>${P.project.use ? `<p class="use">${esc(P.project.use)}</p>` : ''}</div></section>`;
  if (p.kind === 'dig') { const dig = P.geometry.callBeforeYouDig || {}; return `<section class="panel" style="${at(p)}"><div class="ph">Call before you dig</div><div class="pad" data-fit style="flex:1 1 0;display:grid;grid-template-columns:${p.img || 1.5}in 1fr;gap:0.16in;align-items:center">${dig.src ? `<img src="${esc(dig.src)}" alt="811" style="width:${p.img || 1.5}in;display:block">` : `<div class="phd" style="height:${p.img || 1.5}in;font-size:22pt">811</div>`}<div>${(dig.text || []).map(t => `<p style="font:500 9.5pt/1.28 var(--f-body);margin-bottom:0.05in">${rich(t, P)}</p>`).join('')}</div></div></section>`; }
  if (p.kind === 'scope') return `<section class="panel" style="${at(p)}"><div class="ph">Scope</div><div class="pad cvs" data-fit style="flex:1 1 0">${(P.scope || []).map(s => `<div class="sc ${s.kind}"><div class="sk1">${s.kind === 'n' ? chip('n', 'New') : s.kind === 'e' ? chip('e', 'Existing') : chip('o', s.tag || 'Separate permit')}</div><div><b>${esc(s.item)}</b><span>${rich(s.text, P)}</span></div></div>`).join('')}</div></section>`;
  if (p.kind === 'open') { const st = STATUS[P.status] || STATUS.draft, openL = openItems(P), closed = st.issue ? [] : closedItems(P);
    const open = openL.map((o, j) => `<div class="oi"><i class="tri"><b>${j + 1}</b></i><div><b>${esc(o.title)}</b><span>${rich(o.text, P)}</span><em>${esc(o.who || 'Engineer')}</em></div></div>`).join('');
    const done = closed.map(o => `<div class="oi done"><i class="ok"><svg viewBox="0 0 16 16"><path d="M3 8.6l3.2 3L13 4.6" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></i><div><b>${esc(o.title)}</b><span>${esc(o.answer)}</span></div></div>`).join('');
    return `<section class="panel" style="${at(p)}"><div class="ph ${openL.length ? 'red' : ''}">Open items · ${openL.length || 'none'}${openL.length ? ' · the set cannot be issued while this list has entries' : ''}</div><div class="pad cvo" data-fit style="flex:1 1 0;columns:${p.columns || 3};column-gap:0.25in">${open}${done}</div></section>`; }
  return '';
}
const coverIndex = P => `<table class="idx cvi">${P.sheets.map(s => `<tr><td><b>${esc(s.no)}</b></td><td>${esc(s.name)}</td></tr>`).join('')}</table>`;
function cadPanel(P, p) {
  if (p.kind) return coverBits(P, p);
  const ins = (p.inserts || []).map(n => ({ ...n, html: n.index ? coverIndex(P) : n.placeholder ? `<div class="phd">${esc(n.placeholder)}</div>` : n.img ? `<img src="${esc(n.img)}" alt="${esc(n.alt || '')}" style="width:100%;height:100%;object-fit:${n.fit || 'cover'};display:block">` : n.html ? `<div class="nat cn scp" style="padding:.08in .1in;font-size:${n.size || 8.6}pt"><h4>${esc(n.title || '')}</h4>${n.html}</div>` : `<div><b>${esc(n.title || '')}</b><span>${rich(n.text || '', P)}</span></div>` }));
  if (p.placeholder) return panel(p.num || '', p.title, 0, `<div class="phd${p.white ? ' wh' : ''}">${esc(p.placeholder)}</div>`, { style: at(p), note: p.note, scale: p.scale || 'Not to scale' });
  if (p.html) return `<section class="panel" style="${at(p)}">${p.bare ? `<span class="vn" hidden>${esc(p.title)}</span>` : `<div class="ph${p.red ? ' red' : ''}">${esc(p.title)}</div>`}<div class="pad nat ${p.cls || ''}" data-fit style="flex:1 1 0;min-height:0;overflow:hidden${p.columns ? `;columns:${p.columns};column-gap:${p.gap || 0.28}in;column-fill:${p.fill || 'auto'}` : ''}${p.size ? `;font-size:${p.size}pt` : ''}${p.zoom ? `;zoom:${p.zoom}` : ''}">${p.html}</div></section>`;
  if (p.img) return panel(p.num || '', p.title, 0, `<img src="${esc(p.img)}" alt="${esc(p.title)}" style="max-width:100%;max-height:100%;object-fit:contain;display:block">`, { style: at(p), note: p.note, scale: p.scale || 'Not to scale' });
  if (p.text) return `<section class="panel" style="${at(p)}"><div class="ph${p.red ? ' red' : ''}">${esc(p.title)}</div><div class="pad cadtx" data-fit style="flex:1 1 0;min-height:0;overflow:hidden">${(p.items || []).map(t => `<p style="font:500 10.5pt/1.32 var(--f-body);margin-bottom:0.07in">${rich(t, P)}</p>`).join('')}</div></section>`;
  const [x0, y0, x1, y1] = p.crop;
  let f = 1; if (p.nts) f = Math.min((p.w - 0.1) / (x1 - x0), (p.h - (p.footer === false ? 0.1 : 0.55)) / (y1 - y0));
  let svg = cadView(p.page, p.crop, f, p.pics, ins, p.noOverlay, p.marks, p.shade, p.over);
  if (p.join) svg = `<div style="display:flex;flex:0 0 auto">${svg}${cadView(p.join.page, p.join.crop, f, null, null, false, null, p.shade)}</div>`;   // a second window set flush against the first (same scale)
  if (p.footer === false) return `<section class="panel" style="${at(p)}"><div class="view"><span class="vn" hidden>${esc(p.title)}</span>${svg}</div></section>`;
  const out = panel(p.num || '', p.title, p.scale ? 0 : p.den, svg, { style: at(p), note: p.note, scale: p.nts ? 'Not to scale' : p.scale });
  return p.hideTitle ? out.replace('<span class="vn">', '<span class="vn" style="display:none">').replace('<span class="vb">', '<span class="vb" style="display:none">') : out;   // the CAD view already carries its own title bubble
}

function sheetCad(P, G, sh, i, n) {
  const cfg = (P.geometry.sheets || {})[sh.no] || { panels: [] };
  return sheet(P, sh, i, n, 's-cad', `<div class="cadgrid" style="position:relative;flex:0 0 ${BODY_H + (cfg.tight ? 0.1 : 0)}in;width:${BODY_W}in${cfg.tight ? ';margin-top:-0.1in' : ''}">${cfg.panels.map(p => cadPanel(P, p)).join('')}</div>`);
}

// the office sheet: the kit's cover, with the picture taken from the plots instead of an isometric
function sheetCoverCad(P, G, sh, i, n, sheets) {
  const st = STATUS[P.status] || STATUS.draft, cv = P.geometry.coverView, dig = P.geometry.callBeforeYouDig;
  const scope = (P.scope || []).map(s => `<div class="sc ${s.kind}"><div class="sk1">${s.kind === 'n' ? chip('n', 'New') : s.kind === 'e' ? chip('e', 'Existing') : chip('o', s.tag || 'Separate permit')}</div><div><b>${esc(s.item)}</b><span>${rich(s.text, P)}</span></div></div>`).join('');
  const notes = (P.notes || []).map(grp => `<h4>${esc(grp.title)}</h4><ol start="${grp.start || 1}">${grp.items.map(t => `<li>${rich(t, P)}</li>`).join('')}</ol>`).join('');
  const openL = openItems(P), closed = st.issue ? [] : closedItems(P);
  const open = openL.map((o, j) => `<div class="oi"><i class="tri"><b>${j + 1}</b></i><div><b>${esc(o.title)}</b><span>${rich(o.text, P)}</span><em>${esc(o.who || 'Engineer')}</em></div></div>`).join('');
  const done = closed.map(o => `<div class="oi done"><i class="ok"><svg viewBox="0 0 16 16"><path d="M3 8.6l3.2 3L13 4.6" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></i><div><b>${esc(o.title)}</b><span>${esc(o.answer)}</span></div></div>`).join('');
  const crit = (P.criteria || []).map(c => `<tr><td>${esc(c.k)}</td><td>${c.v ? esc(c.v) : chip('r', 'Engineer')}</td></tr>`).join('');
  const idx = sheets.map(s => `<tr><td><b>${esc(s.no)}</b></td><td>${esc(s.name)}</td><td>${esc(s.what || '')}</td></tr>`).join('');
  const key = cv ? cadView(cv.page, cv.crop, Math.min(7.3 / (cv.crop[2] - cv.crop[0]), (cv.h || 3.2) / (cv.crop[3] - cv.crop[1]))) : '';
  const legend = `<div class="lg">
    <div><i class="sw e"></i><b>CAD linework</b><span>Sheets after this one are redrawn from the engineer's DWG files at true paper size. Lighter grey lines are the lighter CAD layers.</span></div>
    <div><i class="tri"></i><b>Engineer</b><span>A value or decision the engineer still owes. Do not build from it until it is filled in.</span></div>
    <div><i class="pm">±</i><b>Not confirmed</b><span>Verify in field (V.I.F.) before building from it.</span></div></div>`;
  const body = `
  <div class="cover">
    <div class="ctop" style="flex:${notes ? `0 0 ${P.geometry.coverTop || 16.6}in` : '1 1 0'}">
      <div class="col">
        <section class="panel"><div class="pad job big" data-fit><label>The job</label><h2>${esc(P.summary.headline)}</h2><p>${esc(P.summary.text)}</p>${P.project.use ? `<p class="use">${esc(P.project.use)}</p>` : ''}</div></section>
        ${cv ? panel('', cv.title || 'Key view', 0, key, { cls: 'grow', note: cv.note || '', scale: 'Not to scale' }) : ''}
        ${dig ? `<section class="panel"><div class="ph">Call before you dig</div><div class="pad" data-fit style="display:grid;grid-template-columns:1.9in 1fr;gap:0.2in;align-items:center"><img src="${esc(dig.src)}" alt="811" style="width:1.9in;display:block"><div>${(dig.text || []).map(t => `<p style="font:500 11pt/1.3 var(--f-body);margin-bottom:0.06in">${rich(t, P)}</p>`).join('')}</div></div></section>` : ''}
        <section class="panel"><div class="ph">How to read this set</div><div class="pad" data-fit>${legend}<p class="how">${esc(P.summary.howToRead || '')}</p></div></section>
      </div>
      <div class="col">
        <section class="panel"><div class="ph">Scope</div><div class="pad" data-fit>${scope}</div></section>
        <section class="panel grow"><div class="ph">Design criteria, as stated on the drawings</div><div class="pad" data-fit><table class="kv">${crit}</table></div></section>
      </div>
      <div class="col">
        <section class="panel grow"><div class="ph">Sheet index</div><div class="pad" data-fit><table class="idx">${idx}</table></div></section>
      </div>
      <div class="col">
        <section class="panel grow"><div class="ph ${openL.length ? 'red' : ''}">Open items · ${openL.length || 'none'}</div><div class="pad" data-fit>${open}${openL.length ? `<p class="how">The set cannot be issued for permit or construction while this list has entries.</p>` : ''}${done ? `<h4 class="oih">Answered</h4>${done}` : ''}</div></section>
      </div>
    </div>
    ${notes ? `<section class="panel grow"><div class="ph">Notes for this set</div><div class="pad notes" data-fit style="columns:3;column-gap:0.35in">${notes}</div></section>` : ''}
  </div>`;
  return sheet(P, sh, i, n, 's-cover', body);
}

const JOB = { type: 'cadset', derive: P => ({}), picture: () => ({ svg: () => '' }), field: { details: [] } };

// The kit lays out cover / field / reserved sheets. This job type adds "cad" sheets and its own cover,
// and adds one check to the audit: every CAD window must print at the size it was plotted.
const kitAudit = audit;
renderSet = function (P) {
  setUnits('in'); REF = {}; cadDefs();
  const sheets = P.sheets, n = sheets.length, set = document.getElementById('set');
  const make = { cover: (P.geometry.sheets || {})[sheets[0].no] ? sheetCad : sheetCoverCad, reserved: sheetReserved, cad: sheetCad };
  set.innerHTML = sheets.map((sh, i) => (make[sh.type] || sheetReserved)(P, {}, sh, i, n, sheets)).join('');
  if (P.issue && P.issue.copyright) set.querySelectorAll('.tb-rev').forEach(e => e.insertAdjacentHTML('beforebegin', `<div class="tb-cr">${esc(P.issue.copyright)}</div>`));   // one small line in every title block
  if ((P.firm || {}).accent) set.style.setProperty('--brand', P.firm.accent); else set.style.removeProperty('--brand');
  document.title = [P.project.address, P.project.title].filter(Boolean).join(' · ');
};
audit = function (P) {
  const out = kitAudit(P), set = document.getElementById('set'), zoom = set.style.zoom; set.style.zoom = 1;
  for (const s of document.querySelectorAll('svg.cadv')) {
    const where = (s.closest('.sheet')?.dataset.sheet || '?') + ' · ' + (s.closest('.panel')?.querySelector('.vn')?.textContent || 'view');
    if (!document.getElementById('pg-' + s.dataset.page)) { out.push(`${where}: source sheet "${s.dataset.page}" is missing`); continue; }
    if (s.dataset.nts) continue;
    const want = +s.dataset.w, got = s.getBoundingClientRect().width / 96;
    if (Math.abs(got - want) / want > 0.003) out.push(`${where}: plotted at ${(100 * got / want).toFixed(1)}% of its true size`);
  }
  for (const sh of P.sheets) if (sh.type === 'cad') for (const p of ((P.geometry.sheets || {})[sh.no] || { panels: [] }).panels)
    if (p.x < 0 || p.y < 0 || p.x + p.w > BODY_W + 0.001 || p.y + p.h > BODY_H + (((P.geometry.sheets || {})[sh.no] || {}).tight ? 0.1 : 0) + 0.001) out.push(`${sh.no} · ${p.title}: panel runs off the sheet`);
  set.style.zoom = zoom;
  return out;
};
// thinner view title bar on CAD sheets, so a full plotted page fits under the status band
